import { test, expect } from '@playwright/test';

test.describe('Multi-Step Form Progress Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
  });

  test('should display progress indicator and update on each step', async ({ page }) => {
    // Verify initial state
    const progressIndicator = page.getByTestId('progress-indicator');
    await expect(progressIndicator).toBeVisible();
    const step1 = page.getByRole('button', { name: /step 1/i });
    await expect(step1).toBeVisible();
    const step2 = page.getByRole('button', { name: /step 2/i });
    await expect(step2).toBeVisible();
    const step3 = page.getByRole('button', { name: /step 3/i });
    await expect(step3).toBeVisible();

    // Fill in step 1
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john@example.com');
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify progress indicator updated to step 2
    await expect(progressIndicator).toContainText('Step 2 of 3');
    await expect(step1).toHaveAttribute('aria-current', 'step');
    await expect(step2).toHaveAttribute('aria-current', 'step');

    // Fill in step 2
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('555-1234');
    const addressInput = page.getByLabel('Address');
    await addressInput.fill('123 Main St');
    await nextButton.click();

    // Verify progress indicator updated to step 3
    await expect(progressIndicator).toContainText('Step 3 of 3');
    await expect(step2).toHaveAttribute('aria-current', 'step');
    await expect(step3).toHaveAttribute('aria-current', 'step');

    // Fill in step 3 and submit
    const countrySelect = page.getByLabel('Country');
    await countrySelect.selectOption('USA');
    const termsCheckbox = page.getByLabel('I agree to terms');
    await termsCheckbox.click();
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should handle navigation back and forward with progress indicator', async ({ page }) => {
    // Navigate to step 2
    const step1 = page.getByRole('button', { name: /step 1/i });
    await step1.click();
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify progress indicator is on step 2
    const progressIndicator = page.getByTestId('progress-indicator');
    await expect(progressIndicator).toContainText('Step 2 of 3');

    // Navigate back to step 1
    const backButton = page.getByRole('button', { name: /back/i });
    await backButton.click();

    // Verify progress indicator updated to step 1
    await expect(progressIndicator).toContainText('Step 1 of 3');
    await expect(step1).toHaveAttribute('aria-current', 'step');
    await expect(step2).not.toHaveAttribute('aria-current', 'step');

    // Navigate forward to step 2
    await nextButton.click();

    // Verify progress indicator updated to step 2
    await expect(progressIndicator).toContainText('Step 2 of 3');
    await expect(step2).toHaveAttribute('aria-current', 'step');

    // Navigate to step 3
    await nextButton.click();

    // Verify progress indicator updated to step 3
    await expect(progressIndicator).toContainText('Step 3 of 3');
    await expect(step3).toHaveAttribute('aria-current', 'step');

    // Verify form data is retained when navigating back and forth
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toHaveValue('John Doe');
    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toHaveValue('john@example.com');
  });
});
